50	class _TesterDashboardState extends State<TesterDashboard> {
51	  bool _initialized = false;
52	  bool _advertising = false;
53	  bool _connected = false;
54	  bool _bonded = false;
55	  bool _subscribed = false;
56	
57	  EcgPattern _currentPattern = EcgPattern.normal;
58	  final int _sampleRate = 250; // Hz
59	  double _timerTime = 0.0;
60	  Timer? _generationTimer;
61	
62	  static const int _frameHeaderBytes = 1;
63	  static const int _sampleBytes = 6;
64	  static const int _defaultPayloadCapBytes = 20;
65	  static const int _maxPayloadCapBytes = 185;
66	
67	  int _payloadCapBytes = _defaultPayloadCapBytes;
68	
69	  // Stats
70	  int _packetsSent = 0;
71	  int _sendErrors = 0;
72	  int _droppedTicks = 0;
73	  bool _sendInFlight = false;
74	
75	  final String _deviceName = "ECG Tester";
76	  static const String _serviceUuid = '0000181d-0000-1000-8000-00805f9b34fb';
77	  static const String _charUuid = '00002a37-0000-1000-8000-00805f9b34fb';
78	
79	  @override
80	  void initState() {
81	    super.initState();
82	    _initBle();
83	  }
84	
85	  Future<void> _initBle() async {
86	    try {
87	      await BlePeripheral.initialize();
88	
89	      BlePeripheral.setAdvertisingStatusUpdateCallback((
90	        bool advertising,
91	        String? error,
92	      ) {
93	        if (mounted) setState(() => _advertising = advertising);
94	      });
95	
96	      BlePeripheral.setConnectionStateChangeCallback((
97	        String deviceId,
98	        bool connected,
99	      ) {
100	        if (mounted) {
101	          setState(() {
102	            _connected = connected;
103	            if (!connected) {
104	              _bonded = false;
105	              _subscribed = false;
106	            }
107	          });
108	        }
109	      });
110	
111	      BlePeripheral.setBondStateChangeCallback((
112	        String deviceId,
113	        BondState bondState,
114	      ) {
115	        if (!mounted) return;
116	        setState(() {
117	          _bonded = bondState == BondState.bonded;
118	        });
119	      });
120	
121	      BlePeripheral.setCharacteristicSubscriptionChangeCallback((
122	        String deviceId,
123	        String characteristicId,
124	        bool isSubscribed,
125	        String? name,
126	      ) {
127	        if (!mounted) return;
128	        if (characteristicId.toLowerCase() == _charUuid.toLowerCase()) {
129	          setState(() {
130	            _subscribed = isSubscribed;
131	          });
132	        }
133	      });
134	
135	      await BlePeripheral.addService(
136	        BleService(
137	          uuid: _serviceUuid,
138	          primary: true,
139	          characteristics: [
140	            BleCharacteristic(
141	              uuid: _charUuid,
142	              properties: [
143	                CharacteristicProperties.read.index,
144	                CharacteristicProperties.notify.index,
145	              ],
146	              permissions: [AttributePermissions.readable.index],
147	            ),
148	          ],
149	        ),
150	      );
151	
152	      if (!mounted) return;
153	      setState(() => _initialized = true);
154	    } catch (e) {
155	      debugPrint('BLE Init failed: $e');
156	    }
157	  }
158	
159	  int _androidSdkInt() {
160	    final match = RegExp(
161	      r'SDK\s*(\d+)',
162	    ).firstMatch(Platform.operatingSystemVersion);
163	    return int.tryParse(match?.group(1) ?? '') ?? 31;
164	  }
165	
166	  Future<bool> _ensureBlePermissions() async {
167	    if (!Platform.isAndroid) return true;
168	
169	    final sdkInt = _androidSdkInt();
170	    if (sdkInt >= 31) {
171	      final statuses = await [
172	        Permission.bluetoothAdvertise,
173	        Permission.bluetoothConnect,
174	      ].request();
175	      return (statuses[Permission.bluetoothAdvertise]?.isGranted ?? false) &&
176	          (statuses[Permission.bluetoothConnect]?.isGranted ?? false);
177	    }
178	
179	    final locationStatus = await Permission.locationWhenInUse.request();
180	    return locationStatus.isGranted;
181	  }
182	
183	  @override
184	  void dispose() {
185	    _generationTimer?.cancel();
186	    BlePeripheral.stopAdvertising();
187	    super.dispose();
188	  }
189	
190	  void _toggleAdvertising() async {
191	    if (_advertising) {
192	      await BlePeripheral.stopAdvertising();
193	      _generationTimer?.cancel();
194	      if (mounted) {
195	        setState(() {
196	          _advertising = false;
197	          _bonded = false;
198	          _subscribed = false;
199	        });
200	      }
201	      return;
202	    }
203	
204	    final hasPermissions = await _ensureBlePermissions();
205	    if (!hasPermissions) {
206	      debugPrint('BLE permissions denied, cannot advertise');
207	      return;
208	    }
209	
210	    try {
211	      await BlePeripheral.startAdvertising(
212	        services: [_serviceUuid],
213	        localName: "ECG",
214	      );
215	      _startGeneration();
216	      if (mounted) setState(() => _advertising = true);
217	    } catch (e) {
218	      debugPrint('Advertising failed: $e');
219	      try {
220	        await BlePeripheral.startAdvertising(services: [], localName: "ECG");
221	        _startGeneration();
222	        if (mounted) setState(() => _advertising = true);
223	      } catch (fallbackError) {
224	        debugPrint('Advertising fallback failed: $fallbackError');
225	      }
226	    }
227	  }
228	
229	  int _samplesPerPacket() {
230	    final available = _payloadCapBytes - _frameHeaderBytes;
231	    final samples = available ~/ _sampleBytes;
232	    return samples < 1 ? 1 : samples;
233	  }
234	
235	  bool _isSizeError(Object error) {
236	    final message = error.toString().toLowerCase();
237	    return message.contains('too large') ||
238	        message.contains('invalid attribute value length') ||
239	        message.contains('mtu') ||
240	        message.contains('133');
241	  }
242	
243	  void _applySafePayloadFallback() {
244	    if (_payloadCapBytes != _defaultPayloadCapBytes) {
245	      _payloadCapBytes = _defaultPayloadCapBytes;
246	      _startGeneration();
247	    }
248	  }
249	
250	  void _startGeneration() {
251	    _generationTimer?.cancel();
252	    _packetsSent = 0;
253	    _sendErrors = 0;
254	    _droppedTicks = 0;
255	    _sendInFlight = false;
256	    _timerTime = 0;
257	
258	    final samplesPerPacket = _samplesPerPacket();
259	    final intervalMs = max(1, 1000 * samplesPerPacket ~/ _sampleRate);
260	    final interval = Duration(milliseconds: intervalMs);
261	
262	    _generationTimer = Timer.periodic(interval, (timer) {
263	      if (!_advertising || _sendInFlight) return;
264	      _sendInFlight = true;
265	
266	      () async {
267	        try {
268	          final byteData = ByteData(
269	            _frameHeaderBytes + samplesPerPacket * _sampleBytes,
270	          );
271	          byteData.setUint8(0, 0xEC);
272	
273	          for (int i = 0; i < samplesPerPacket; i++) {
274	            final rawLeads = _generateSample();
275	            final int baseOffset = _frameHeaderBytes + i * _sampleBytes;
276	            byteData.setInt16(baseOffset, rawLeads[0], Endian.little);
277	            byteData.setInt16(baseOffset + 2, rawLeads[1], Endian.little);
278	            byteData.setInt16(baseOffset + 4, rawLeads[2], Endian.little);
279	            _timerTime += 1.0 / _sampleRate;
280	          }
281	
282	          final bytes = byteData.buffer.asUint8List();
283	
284	          if (bytes.length > _payloadCapBytes ||
285	              bytes.length > _maxPayloadCapBytes) {
286	            if (mounted) {
287	              setState(() {
288	                _droppedTicks++;
289	              });
290	            }
291	            return;
292	          }
293	
294	          await BlePeripheral.updateCharacteristic(
295	            characteristicId: _charUuid,
296	            value: bytes,
297	          );
298	          if (mounted) {
299	            setState(() {
300	              _packetsSent++;
301	            });
302	          }
303	        } catch (e) {
304	          if (mounted) {
305	            setState(() {
306	              _sendErrors++;
307	              _droppedTicks++;
308	            });
309	          }
310	          debugPrint('Send error: $e');
311	          if (_isSizeError(e)) {
312	            _applySafePayloadFallback();
313	          }
314	        } finally {
315	          _sendInFlight = false;
316	        }
317	      }();
318	    });
319	  }
320	
321	  List<int> _generateSample() {
322	    if (_currentPattern == EcgPattern.leadsOff) return [-1, -1, -1];
323	
324	    double hr = 75;
325	    if (_currentPattern == EcgPattern.tachycardia) hr = 140;
326	    if (_currentPattern == EcgPattern.heartFailure) hr = 55;
327	
328	    final double beatInterval = 60.0 / hr;
329	    final double phase = (_timerTime % beatInterval) / beatInterval;
330	
331	    double p = _wave(phase, 0.1, 0.05, 0.02);
332	    double qrs = _qrs(phase, 0.15, 0.05);
333	    double t = _wave(phase, 0.35, 0.12, 0.06);
334	
335	    double leadI = 0.0;
336	    double leadII = 0.0;
337	    double leadIII = 0.0;
338	
339	    switch (_currentPattern) {
340	      case EcgPattern.mi:
341	        double stElevation = _wave(phase, 0.22, 0.1, 0.08);
342	        leadII = p + qrs + t + stElevation;
343	        leadI = p + (qrs * 0.7) + (t * 0.5);
344	        break;
345	      case EcgPattern.heartFailure:
346	        leadII = (p + qrs + (t * 1.5)) * 0.4;
347	        leadI = (p + (qrs * 0.6) + t) * 0.3;
348	        break;
349	      case EcgPattern.conduction:
350	        double wideQrs = _qrs(phase, 0.15, 0.12);
351	        leadII = p + wideQrs + t;
352	        leadI = p + (wideQrs * 0.8) + (t * 0.6);
353	        break;
354	      case EcgPattern.noisy:
355	        final noise = (Random().nextDouble() - 0.5) * 0.4;
356	        leadII = p + qrs + t + noise;
357	        leadI = p + qrs + t + noise;
358	        break;
359	      default:
360	        leadII = p + qrs + t;
361	        leadI = p + (qrs * 0.8) + (t * 0.7);
362	    }
363	
364	    leadIII = leadII - leadI;
365	
366	    int toAdc(double val) => (2048 + (val * 1000)).clamp(0, 4094).toInt();
367	    return [toAdc(leadI), toAdc(leadII), toAdc(leadIII)];
368	  }
369	
370	  double _wave(double phase, double pos, double width, double amp) {
371	    return amp * exp(-pow(phase - pos, 2) / (2 * pow(width, 2)));
372	  }
373	
374	  double _qrs(double phase, double pos, double width) {
375	    double q = -0.1 * exp(-pow(phase - (pos - 0.02), 2) / 0.0001);
376	    double r = 1.2 * exp(-pow(phase - pos, 2) / (width * 0.1));
377	    double s = -0.2 * exp(-pow(phase - (pos + 0.02), 2) / 0.0002);
378	    return q + r + s;
379	  }
