32	  bool _bleConnected = false;
33	  bool _isScanning = false;
34	
35	  static const int _visibleSamples = 500;
36	  final List<double> _leadIData = [];
37	  final List<double> _leadIIData = [];
38	  final List<double> _leadIIIData = [];
39	
40	  EcgPrediction? _prediction;
41	  late AnimationController _pulseController;
42	  late AnimationController _heartbeatController;
43	
