90	  void _onEcgData(List<EcgSample> samples) {
91	    if (!mounted) return;
92	    widget.inferenceService.addSamples(samples);
93	
94	    setState(() {
95	      for (final sample in samples) {
96	        final mv = sample.toMillivolts();
97	        _leadIData.add(mv[0]);
98	        _leadIIData.add(mv[1]);
99	        _leadIIIData.add(mv[2]);
100	
101	        if (_leadIData.length > _visibleSamples) _leadIData.removeAt(0);
102	        if (_leadIIData.length > _visibleSamples) _leadIIData.removeAt(0);
103	        if (_leadIIIData.length > _visibleSamples) _leadIIIData.removeAt(0);
104	
105	        // Simple R-peak detection on Lead II for HR estimation
106	        _detectRPeak(mv[1]);
107	      }
108	    });
109	  }
110	
111	  void _detectRPeak(double val) {
112	    // Threshold-based: if value > 1.2mV and previous was lower
113	    if (_leadIIData.length >= 3) {
114	      final prev = _leadIIData[_leadIIData.length - 2];
115	      final prevPrev = _leadIIData[_leadIIData.length - 3];
116	      if (prev > 1.0 && prev > val && prev > prevPrev) {
117	        final now = DateTime.now().millisecondsSinceEpoch;
118	        _rPeakTimestamps.add(now);
119	        if (_rPeakTimestamps.length > 10) _rPeakTimestamps.removeAt(0);
120	
121	        // Heartbeat animation
122	        _heartbeatController.forward(from: 0);
123	
124	        // Compute HR from last 5 intervals
125	        if (_rPeakTimestamps.length >= 3) {
126	          int totalInterval = 0;
127	          int count = 0;
128	          for (int i = _rPeakTimestamps.length - 1; i > 0 && count < 5; i--) {
129	            final interval = _rPeakTimestamps[i] - _rPeakTimestamps[i - 1];
130	            if (interval > 300 && interval < 2000) {
131	              totalInterval += interval;
132	              count++;
133	            }
134	          }
135	          if (count > 0) {
136	            _estimatedHR = (60000 * count / totalInterval).round();
137	          }
138	        }
139	      }
140	    }
141	  }
