import 'dart:async';
import 'dart:math';
import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';
import '../../bluetooth/data/ble_service.dart';
import '../../bluetooth/data/ecg_data_model.dart';
import '../../ecg/data/ecg_inference_service.dart';
import '../../ecg/data/notification_service.dart';
import '../../fall_detection/presentation/fall_test_page.dart';
import '../../history/data/ecg_history_service.dart';

class EcgMonitorPage extends StatefulWidget {
  final BleService bleService;
  final EcgInferenceService inferenceService;
  final NotificationService notificationService;
  final EcgHistoryService historyService;

  const EcgMonitorPage({
    super.key,
    required this.bleService,
    required this.inferenceService,
    required this.notificationService,
    required this.historyService,
  });

  @override
  State<EcgMonitorPage> createState() => _EcgMonitorPageState();
}

class _EcgMonitorPageState extends State<EcgMonitorPage>
    with TickerProviderStateMixin {
  bool _bleConnected = false;
  bool _isScanning = false;

  static const int _visibleSamples = 500;
  final List<double> _leadIData = [];
  final List<double> _leadIIData = [];
  final List<double> _leadIIIData = [];

  EcgPrediction? _prediction;
  late AnimationController _pulseController;
  late AnimationController _heartbeatController;

  StreamSubscription? _ecgSub;
  StreamSubscription? _connectionSub;
  StreamSubscription? _scanSub;
  StreamSubscription? _predictionSub;

  // Estimated heart rate from R-R intervals
  int _estimatedHR = 0;
  final List<int> _rPeakTimestamps = [];

  @override
  void initState() {
    super.initState();

    _pulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1000),
    );
    _heartbeatController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 600),
    );

    _connectionSub = widget.bleService.connectionStream.listen((connected) {
      if (mounted) {
        setState(() => _bleConnected = connected);
        if (!connected) {
          _leadIData.clear();
          _leadIIData.clear();
          _leadIIIData.clear();
          _prediction = null;
          widget.inferenceService.reset();
          _pulseController.stop();
          _estimatedHR = 0;
          _rPeakTimestamps.clear();
        }
      }
    });

    _scanSub = widget.bleService.scanStream.listen((scanning) {
      if (mounted) setState(() => _isScanning = scanning);
    });

    _ecgSub = widget.bleService.ecgStream.listen(_onEcgData);
    _predictionSub = widget.inferenceService.predictions.listen(_onPrediction);
  }

  void _onEcgData(List<EcgSample> samples) {
    if (!mounted) return;
    widget.inferenceService.addSamples(samples);

    setState(() {
      for (final sample in samples) {
        final mv = sample.toMillivolts();
        _leadIData.add(mv[0]);
        _leadIIData.add(mv[1]);
        _leadIIIData.add(mv[2]);

        if (_leadIData.length > _visibleSamples) _leadIData.removeAt(0);
        if (_leadIIData.length > _visibleSamples) _leadIIData.removeAt(0);
        if (_leadIIIData.length > _visibleSamples) _leadIIIData.removeAt(0);

        // Simple R-peak detection on Lead II for HR estimation
        _detectRPeak(mv[1]);
      }
    });
  }

  void _detectRPeak(double val) {
    // Threshold-based: if value > 1.2mV and previous was lower
    if (_leadIIData.length >= 3) {
      final prev = _leadIIData[_leadIIData.length - 2];
      final prevPrev = _leadIIData[_leadIIData.length - 3];
      if (prev > 1.0 && prev > val && prev > prevPrev) {
        final now = DateTime.now().millisecondsSinceEpoch;
        _rPeakTimestamps.add(now);
        if (_rPeakTimestamps.length > 10) _rPeakTimestamps.removeAt(0);

        // Heartbeat animation
        _heartbeatController.forward(from: 0);

        // Compute HR from last 5 intervals
        if (_rPeakTimestamps.length >= 3) {
          int totalInterval = 0;
          int count = 0;
          for (int i = _rPeakTimestamps.length - 1; i > 0 && count < 5; i--) {
            final interval = _rPeakTimestamps[i] - _rPeakTimestamps[i - 1];
            if (interval > 300 && interval < 2000) {
              totalInterval += interval;
              count++;
            }
          }
          if (count > 0) {
            _estimatedHR = (60000 * count / totalInterval).round();
          }
        }
      }
    }
  }

  void _onPrediction(EcgPrediction prediction) {
    if (!mounted) return;
    setState(() {
      _prediction = prediction;
      if (prediction.isAbnormal) {
        _pulseController.repeat(reverse: true);
      } else {
        _pulseController.stop();
        _pulseController.value = 0;
      }
    });

    // Fire notification and save to history
    widget.notificationService.checkAndNotify(prediction);
    if (prediction.isAbnormal) {
      widget.historyService.addAlert(prediction);
    }
  }

  void _toggleBle() {
    if (_bleConnected) {
      widget.bleService.disconnect();
    } else if (!_isScanning) {
      setState(() {
        _leadIData.clear();
        _leadIIData.clear();
        _leadIIIData.clear();
        _prediction = null;
        _estimatedHR = 0;
        _rPeakTimestamps.clear();
      });
      widget.inferenceService.reset();
      widget.bleService.startScanAndConnect();
    }
  }

  @override
  void dispose() {
    _ecgSub?.cancel();
    _connectionSub?.cancel();
    _scanSub?.cancel();
    _predictionSub?.cancel();
    _pulseController.dispose();
    _heartbeatController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF0D1B2A),
      body: SafeArea(
        child: Column(
          children: [
            _buildTopBar(),
            Expanded(
              child: SingleChildScrollView(
                physics: const AlwaysScrollableScrollPhysics(),
                child: Column(
                  children: [
                    const SizedBox(height: 8),
                    _buildStatusCards(),
                    const SizedBox(height: 12),
                    _buildBleDiagnosticsCard(),
                    const SizedBox(height: 16),
                    if (_prediction != null || _bleConnected)
                      _buildPredictionCard(),
                    if (_bleConnected && !widget.inferenceService.isModelLoaded)
                      _buildModelWarning(),
                    const SizedBox(height: 16),
                    _buildLeadChart(
                      'Lead I',
                      _leadIData,
                      const Color(0xFFFF5252),
                    ),
                    const SizedBox(height: 12),
                    _buildLeadChart(
                      'Lead II',
                      _leadIIData,
                      const Color(0xFF69F0AE),
                    ),
                    const SizedBox(height: 12),
                    _buildLeadChart(
                      'Lead III',
                      _leadIIIData,
                      const Color(0xFF40C4FF),
                    ),
                    const SizedBox(height: 24),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildTopBar() {
    return Container(
      padding: const EdgeInsets.fromLTRB(20, 12, 16, 12),
      decoration: const BoxDecoration(
        color: Color(0xFF1A2332),
        border: Border(bottom: BorderSide(color: Color(0xFF263545))),
      ),
      child: Row(
        children: [
          const Icon(Icons.monitor_heart, color: Colors.tealAccent, size: 26),
          const SizedBox(width: 10),
          const Text(
            'ECG Monitor',
            style: TextStyle(
              fontSize: 20,
              fontWeight: FontWeight.bold,
              color: Colors.white,
              letterSpacing: 0.5,
            ),
          ),
          const Spacer(),
          IconButton(
            onPressed: () => Navigator.of(
              context,
            ).push(MaterialPageRoute(builder: (_) => const FallTestPage())),
            icon: const Icon(Icons.science, color: Colors.white54, size: 22),
            tooltip: 'Fall Detection Test',
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(),
          ),
          const SizedBox(width: 12),
          if (_isScanning)
            const SizedBox(
              width: 20,
              height: 20,
              child: CircularProgressIndicator(
                color: Colors.tealAccent,
                strokeWidth: 2,
              ),
            )
          else
            _buildConnectButton(),
        ],
      ),
    );
  }

  Widget _buildConnectButton() {
    return GestureDetector(
      onTap: _toggleBle,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 7),
        decoration: BoxDecoration(
          color: _bleConnected
              ? Colors.tealAccent.withValues(alpha: 0.15)
              : Colors.white.withValues(alpha: 0.08),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(
            color: _bleConnected
                ? Colors.tealAccent.withValues(alpha: 0.4)
                : Colors.white24,
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              _bleConnected
                  ? Icons.bluetooth_connected
                  : Icons.bluetooth_searching,
              size: 16,
              color: _bleConnected ? Colors.tealAccent : Colors.white54,
            ),
            const SizedBox(width: 6),
            Text(
              _bleConnected ? 'Connected' : 'Connect',
              style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w600,
                color: _bleConnected ? Colors.tealAccent : Colors.white54,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildStatusCards() {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: Row(
        children: [
          // Heart Rate
          Expanded(
            child: _buildStatCard(
              icon: Icons.favorite,
              value: _estimatedHR > 0 ? '$_estimatedHR' : '--',
              unit: 'BPM',
              color: const Color(0xFFFF5252),
              animated: _estimatedHR > 0,
            ),
          ),
          const SizedBox(width: 12),
          // AI Buffer
          Expanded(
            child: _buildStatCard(
              icon: Icons.psychology,
              value:
                  '${widget.inferenceService.bufferFill.toStringAsFixed(0)}%',
              unit: 'AI Buffer',
              color: Colors.tealAccent,
              animated: false,
            ),
          ),
          const SizedBox(width: 12),
          // Status
          Expanded(
            child: _buildStatCard(
              icon: _bleConnected ? Icons.sensors : Icons.sensors_off,
              value: _bleConnected ? 'LIVE' : 'OFF',
              unit: 'Signal',
              color: _bleConnected ? const Color(0xFF69F0AE) : Colors.white38,
              animated: false,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildStatCard({
    required IconData icon,
    required String value,
    required String unit,
    required Color color,
    required bool animated,
  }) {
    return Container(
      padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 12),
      decoration: BoxDecoration(
        color: const Color(0xFF1A2332),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: color.withValues(alpha: 0.15)),
      ),
      child: Column(
        children: [
          animated
              ? AnimatedBuilder(
                  animation: _heartbeatController,
                  builder: (context, child) => Transform.scale(
                    scale: 1.0 + _heartbeatController.value * 0.2,
                    child: Icon(icon, color: color, size: 22),
                  ),
                )
              : Icon(icon, color: color, size: 22),
          const SizedBox(height: 6),
          Text(
            value,
            style: TextStyle(
              fontSize: 22,
              fontWeight: FontWeight.bold,
              color: color,
            ),
          ),
          Text(
            unit,
            style: const TextStyle(fontSize: 11, color: Colors.white38),
          ),
        ],
      ),
    );
  }

  Widget _buildBleDiagnosticsCard() {
    final ble = widget.bleService;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: const Color(0xFF1A2332),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: const Color(0xFF263545)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'BLE Diagnostics',
            style: TextStyle(
              color: Colors.white70,
              fontSize: 12,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 12,
            runSpacing: 6,
            children: [
              _diagChip(
                'Notify',
                '${ble.notifySuccessCount}/${ble.notifyAttemptCount}',
              ),
              _diagChip('Packets', '${ble.rawNotificationCount}'),
              _diagChip('Bytes', '${ble.rawNotificationBytes}'),
              _diagChip('Batches', '${ble.parsedBatchCount}'),
              _diagChip('Samples', '${ble.emittedSampleCount}'),
              _diagChip('Drops', '${ble.droppedPacketCount}'),
              _diagChip('Hdr', '${ble.invalidHeaderCount}'),
              _diagChip('Malformed', '${ble.malformedPacketCount}'),
            ],
          ),
        ],
      ),
    );
  }

  Widget _diagChip(String label, String value) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.white12),
      ),
      child: Text(
        '$label: $value',
        style: const TextStyle(
          color: Colors.white60,
          fontSize: 11,
          fontWeight: FontWeight.w500,
        ),
      ),
    );
  }

  Widget _buildPredictionCard() {
    final pred = _prediction;

    if (pred == null) {
      return Container(
        margin: const EdgeInsets.symmetric(horizontal: 16),
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: const Color(0xFF1A2332),
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: const Color(0xFF263545)),
        ),
        child: const Row(
          children: [
            SizedBox(
              width: 18,
              height: 18,
              child: CircularProgressIndicator(
                strokeWidth: 2,
                color: Colors.tealAccent,
              ),
            ),
            SizedBox(width: 12),
            Text(
              'Collecting ECG data for AI analysis...',
              style: TextStyle(color: Colors.white54, fontSize: 13),
            ),
          ],
        ),
      );
    }

    final predColor = Color(pred.colorValue);
    final isAbnormal = pred.isAbnormal;

    return AnimatedBuilder(
      animation: _pulseController,
      builder: (context, child) {
        final glowOpacity = isAbnormal
            ? 0.1 + _pulseController.value * 0.15
            : 0.0;
        return Container(
          margin: const EdgeInsets.symmetric(horizontal: 16),
          padding: const EdgeInsets.all(18),
          decoration: BoxDecoration(
            color: const Color(0xFF1A2332),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color: predColor.withValues(alpha: isAbnormal ? 0.5 : 0.2),
              width: isAbnormal ? 1.5 : 1,
            ),
            boxShadow: isAbnormal
                ? [
                    BoxShadow(
                      color: predColor.withValues(alpha: glowOpacity),
                      blurRadius: 24,
                      spreadRadius: 2,
                    ),
                  ]
                : null,
          ),
          child: Column(
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: predColor.withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Icon(
                      isAbnormal ? Icons.warning_amber : Icons.favorite,
                      color: predColor,
                      size: 24,
                    ),
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'AI Diagnosis',
                          style: TextStyle(fontSize: 11, color: Colors.white38),
                        ),
                        Text(
                          pred.label,
                          style: TextStyle(
                            fontSize: 18,
                            fontWeight: FontWeight.bold,
                            color: predColor,
                          ),
                        ),
                      ],
                    ),
                  ),
                  Column(
                    children: [
                      Text(
                        '${(pred.confidence * 100).toStringAsFixed(0)}%',
                        style: TextStyle(
                          fontSize: 26,
                          fontWeight: FontWeight.bold,
                          color: predColor,
                        ),
                      ),
                      const Text(
                        'Confidence',
                        style: TextStyle(fontSize: 10, color: Colors.white30),
                      ),
                    ],
                  ),
                ],
              ),
              const SizedBox(height: 14),
              ...EcgPrediction.classNames.map((name) {
                final conf = pred.classConfidences[name] ?? 0.0;
                final barColor = Color(
                  EcgPrediction.classColors[name] ?? 0xFF9E9E9E,
                );
                return Padding(
                  padding: const EdgeInsets.only(bottom: 5),
                  child: Row(
                    children: [
                      SizedBox(
                        width: 40,
                        child: Text(
                          name,
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: name == pred.predictedClass
                                ? FontWeight.bold
                                : FontWeight.normal,
                            color: name == pred.predictedClass
                                ? barColor
                                : Colors.white38,
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(3),
                          child: LinearProgressIndicator(
                            value: conf,
                            backgroundColor: barColor.withValues(alpha: 0.08),
                            valueColor: AlwaysStoppedAnimation(barColor),
                            minHeight: 6,
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      SizedBox(
                        width: 36,
                        child: Text(
                          '${(conf * 100).toStringAsFixed(0)}%',
                          style: const TextStyle(
                            fontSize: 11,
                            color: Colors.white38,
                          ),
                          textAlign: TextAlign.right,
                        ),
                      ),
                    ],
                  ),
                );
              }),
            ],
          ),
        );
      },
    );
  }

  Widget _buildModelWarning() {
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 8, 16, 0),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.orange.withValues(alpha: 0.08),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.orange.withValues(alpha: 0.2)),
      ),
      child: const Row(
        children: [
          Icon(Icons.info_outline, color: Colors.orangeAccent, size: 18),
          SizedBox(width: 8),
          Expanded(
            child: Text(
              'AI model not loaded. Put ecg_model.tflite in assets/models/',
              style: TextStyle(fontSize: 12, color: Colors.orangeAccent),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildLeadChart(String title, List<double> data, Color color) {
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16),
      decoration: BoxDecoration(
        color: const Color(0xFF1A2332),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: color.withValues(alpha: 0.1)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
            child: Row(
              children: [
                Container(
                  width: 4,
                  height: 14,
                  decoration: BoxDecoration(
                    color: color,
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
                const SizedBox(width: 8),
                Text(
                  title,
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    color: Colors.white70,
                  ),
                ),
                const Spacer(),
                if (data.isNotEmpty)
                  Text(
                    '${data.last.toStringAsFixed(1)} mV',
                    style: TextStyle(
                      fontSize: 12,
                      color: color.withValues(alpha: 0.7),
                      fontWeight: FontWeight.w500,
                    ),
                  ),
              ],
            ),
          ),
          SizedBox(
            height: 120,
            child: data.isEmpty
                ? Center(
                    child: Text(
                      'Waiting for signal...',
                      style: TextStyle(
                        fontSize: 12,
                        color: Colors.white.withValues(alpha: 0.2),
                      ),
                    ),
                  )
                : Padding(
                    padding: const EdgeInsets.fromLTRB(8, 8, 12, 4),
                    child: _buildChart(data, color),
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildChart(List<double> data, Color color) {
    final spots = <FlSpot>[];
    for (int i = 0; i < data.length; i++) {
      spots.add(FlSpot(i.toDouble(), data[i]));
    }

    double minY = data.reduce(min);
    double maxY = data.reduce(max);
    double range = maxY - minY;
    if (range < 0.1) range = 1.0;
    minY -= range * 0.1;
    maxY += range * 0.1;

    return LineChart(
      LineChartData(
        minY: minY,
        maxY: maxY,
        clipData: const FlClipData.all(),
        gridData: FlGridData(
          show: true,
          horizontalInterval: range / 4,
          getDrawingHorizontalLine: (value) =>
              FlLine(color: color.withValues(alpha: 0.06), strokeWidth: 0.5),
          drawVerticalLine: true,
          verticalInterval: 62.5,
          getDrawingVerticalLine: (value) =>
              FlLine(color: color.withValues(alpha: 0.04), strokeWidth: 0.5),
        ),
        titlesData: const FlTitlesData(show: false),
        borderData: FlBorderData(show: false),
        lineTouchData: const LineTouchData(enabled: false),
        lineBarsData: [
          LineChartBarData(
