85	  Future<void> _initBle() async {
86	    try {
87	      await BlePeripheral.initialize();
88	
89	      BlePeripheral.setAdvertisingStatusUpdateCallback((
90	        bool advertising,
91	        String? error,
92	      ) {
93	        if (mounted) setState(() => _advertising = advertising);
94	      });
95	
96	      BlePeripheral.setConnectionStateChangeCallback((
97	        String deviceId,
98	        bool connected,
99	      ) {
100	        if (mounted) {
101	          setState(() {
102	            _connected = connected;
103	            if (!connected) {
104	              _bonded = false;
105	              _subscribed = false;
106	            }
107	          });
108	        }
109	        if (!connected) {
110	          _restartAdvertisingIfNeeded();
111	        }
112	      });
113	
114	      BlePeripheral.setBondStateChangeCallback((
115	        String deviceId,
116	        BondState bondState,
117	      ) {
118	        if (!mounted) return;
119	        setState(() {
120	          _bonded = bondState == BondState.bonded;
121	        });
122	      });
123	
124	      BlePeripheral.setCharacteristicSubscriptionChangeCallback((
125	        String deviceId,
126	        String characteristicId,
127	        bool isSubscribed,
128	        String? name,
129	      ) {
130	        if (!mounted) return;
131	        if (characteristicId.toLowerCase() == _charUuid.toLowerCase()) {
132	          setState(() {
133	            _subscribed = isSubscribed;
134	          });
135	        }
136	      });
137	
138	      BlePeripheral.setServiceAddedCallback((String serviceId, String? error) {
139	        debugPrint('Service added: $serviceId error=$error');
140	      });
141	
142	      await BlePeripheral.addService(
143	        BleService(
144	          uuid: _serviceUuid,
145	          primary: true,
146	          characteristics: [
147	            BleCharacteristic(
148	              uuid: _charUuid,
149	              properties: [
150	                CharacteristicProperties.read.index,
151	                CharacteristicProperties.notify.index,
152	              ],
153	              permissions: [AttributePermissions.readable.index],
154	            ),
155	          ],
156	        ),
157	      );
158	
159	      // Allow time for the GATT server to fully register the service
160	      // before we expose advertising controls.
161	      await Future.delayed(const Duration(milliseconds: 500));
162	
163	      if (!mounted) return;
164	      setState(() => _initialized = true);
165	    } catch (e) {
166	      debugPrint('BLE Init failed: $e');
167	    }
