170	  int _androidSdkInt() {
171	    final match = RegExp(
172	      r'SDK\s*(\d+)',
173	    ).firstMatch(Platform.operatingSystemVersion);
174	    return int.tryParse(match?.group(1) ?? '') ?? 31;
175	  }
176	
177	  Future<bool> _ensureBlePermissions() async {
178	    if (!Platform.isAndroid) return true;
179	
180	    final sdkInt = _androidSdkInt();
181	    if (sdkInt >= 31) {
182	      final statuses = await [
183	        Permission.bluetoothAdvertise,
184	        Permission.bluetoothConnect,
185	      ].request();
186	      return (statuses[Permission.bluetoothAdvertise]?.isGranted ?? false) &&
187	          (statuses[Permission.bluetoothConnect]?.isGranted ?? false);
188	    }
189	
190	    final locationStatus = await Permission.locationWhenInUse.request();
191	    return locationStatus.isGranted;
192	  }
193	
194	  @override
195	  void dispose() {
196	    _generationTimer?.cancel();
197	    BlePeripheral.stopAdvertising();
198	    super.dispose();
199	  }
200	
201	  void _toggleAdvertising() async {
202	    if (_advertising) {
203	      await BlePeripheral.stopAdvertising();
204	      _generationTimer?.cancel();
205	      if (mounted) {
206	        setState(() {
207	          _advertising = false;
208	          _bonded = false;
209	          _subscribed = false;
210	        });
211	      }
212	      return;
213	    }
214	
215	    final hasPermissions = await _ensureBlePermissions();
216	    if (!hasPermissions) {
217	      debugPrint('BLE permissions denied, cannot advertise');
218	      return;
219	    }
220	
221	    try {
222	      await BlePeripheral.startAdvertising(
223	        services: [_serviceUuid],
224	        localName: "ECG",
225	      );
226	      _startGeneration();
227	      if (mounted) setState(() => _advertising = true);
228	    } catch (e) {
229	      debugPrint('Advertising failed: $e');
230	      try {
231	        await BlePeripheral.startAdvertising(services: [], localName: "ECG");
232	        _startGeneration();
233	        if (mounted) setState(() => _advertising = true);
234	      } catch (fallbackError) {
235	        debugPrint('Advertising fallback failed: $fallbackError');
236	      }
237	    }
238	  }
239	
240	  int _samplesPerPacket() {
241	    final available = _payloadCapBytes - _frameHeaderBytes;
242	    final samples = available ~/ _sampleBytes;
243	    return samples < 1 ? 1 : samples;
244	  }
245	
246	  bool _isSizeError(Object error) {
247	    final message = error.toString().toLowerCase();
248	    return message.contains('too large') ||
249	        message.contains('invalid attribute value length') ||
250	        message.contains('mtu') ||
251	        message.contains('133');
252	  }
253	
254	  void _applySafePayloadFallback() {
255	    if (_payloadCapBytes != _defaultPayloadCapBytes) {
256	      _payloadCapBytes = _defaultPayloadCapBytes;
257	      _startGeneration();
258	    }
259	  }
260	
261	  Future<void> _restartAdvertisingIfNeeded() async {
262	    if (_advertising) return;
263	    try {
264	      await BlePeripheral.startAdvertising(
265	        services: [_serviceUuid],
266	        localName: "ECG",
267	      );
268	      if (mounted) setState(() => _advertising = true);
269	    } catch (e) {
270	      debugPrint('Re-advertising failed: $e');
271	    }
272	  }
273	
274	  void _startGeneration() {
275	    _generationTimer?.cancel();
276	    _packetsSent = 0;
277	    _sendErrors = 0;
278	    _droppedTicks = 0;
279	    _sendInFlight = false;
280	    _timerTime = 0;
281	
282	    final samplesPerPacket = _samplesPerPacket();
283	    final intervalMs = max(1, 1000 * samplesPerPacket ~/ _sampleRate);
284	    final interval = Duration(milliseconds: intervalMs);
285	
286	    _generationTimer = Timer.periodic(interval, (timer) {
287	      if (_sendInFlight) return;
288	      if (!_advertising && !_connected) return;
289	      _sendInFlight = true;
290	
291	      () async {
292	        try {
293	          final byteData = ByteData(
294	            _frameHeaderBytes + samplesPerPacket * _sampleBytes,
295	          );
296	          byteData.setUint8(0, 0xEC);
297	
298	          for (int i = 0; i < samplesPerPacket; i++) {
299	            final rawLeads = _generateSample();
300	            final int baseOffset = _frameHeaderBytes + i * _sampleBytes;
301	            byteData.setInt16(baseOffset, rawLeads[0], Endian.little);
302	            byteData.setInt16(baseOffset + 2, rawLeads[1], Endian.little);
303	            byteData.setInt16(baseOffset + 4, rawLeads[2], Endian.little);
304	            _timerTime += 1.0 / _sampleRate;
305	          }
306	
307	          final bytes = byteData.buffer.asUint8List();
308	
309	          if (bytes.length > _payloadCapBytes ||
310	              bytes.length > _maxPayloadCapBytes) {
311	            if (mounted) {
312	              setState(() {
313	                _droppedTicks++;
314	              });
315	            }
316	            return;
317	          }
318	
319	          await BlePeripheral.updateCharacteristic(
320	            characteristicId: _charUuid,
321	            value: bytes,
322	          );
323	          if (mounted) {
324	            setState(() {
325	              _packetsSent++;
326	            });
327	          }
328	        } catch (e) {
329	          if (mounted) {
330	            setState(() {
331	              _sendErrors++;
332	              _droppedTicks++;
333	            });
334	          }
335	          debugPrint('Send error: $e');
336	          if (_isSizeError(e)) {
337	            _applySafePayloadFallback();
338	          }
339	        } finally {
340	          _sendInFlight = false;
341	        }
342	      }();
343	    });
344	  }
345	
346	  List<int> _generateSample() {
347	    if (_currentPattern == EcgPattern.leadsOff) return [-1, -1, -1];
348	
349	    double hr = 75;
350	    if (_currentPattern == EcgPattern.tachycardia) hr = 140;
351	    if (_currentPattern == EcgPattern.heartFailure) hr = 55;
352	
353	    final double beatInterval = 60.0 / hr;
354	    final double phase = (_timerTime % beatInterval) / beatInterval;
355	
356	    double p = _wave(phase, 0.1, 0.05, 0.02);
357	    double qrs = _qrs(phase, 0.15, 0.05);
358	    double t = _wave(phase, 0.35, 0.12, 0.06);
359	
360	    double leadI = 0.0;
361	    double leadII = 0.0;
362	    double leadIII = 0.0;
363	
364	    switch (_currentPattern) {
365	      case EcgPattern.mi:
366	        double stElevation = _wave(phase, 0.22, 0.1, 0.08);
367	        leadII = p + qrs + t + stElevation;
368	        leadI = p + (qrs * 0.7) + (t * 0.5);
369	        break;
370	      case EcgPattern.heartFailure:
371	        leadII = (p + qrs + (t * 1.5)) * 0.4;
372	        leadI = (p + (qrs * 0.6) + t) * 0.3;
373	        break;
374	      case EcgPattern.conduction:
375	        double wideQrs = _qrs(phase, 0.15, 0.12);
376	        leadII = p + wideQrs + t;
377	        leadI = p + (wideQrs * 0.8) + (t * 0.6);
378	        break;
379	      case EcgPattern.noisy:
380	        final noise = (Random().nextDouble() - 0.5) * 0.4;
381	        leadII = p + qrs + t + noise;
382	        leadI = p + qrs + t + noise;
383	        break;
384	      default:
385	        leadII = p + qrs + t;
386	        leadI = p + (qrs * 0.8) + (t * 0.7);
387	    }
388	
389	    leadIII = leadII - leadI;
390	
391	    int toAdc(double val) => (2048 + (val * 1000)).clamp(0, 4094).toInt();
392	    return [toAdc(leadI), toAdc(leadII), toAdc(leadIII)];
393	  }
394	
395	  double _wave(double phase, double pos, double width, double amp) {
396	    return amp * exp(-pow(phase - pos, 2) / (2 * pow(width, 2)));
397	  }
398	
399	  double _qrs(double phase, double pos, double width) {
400	    double q = -0.1 * exp(-pow(phase - (pos - 0.02), 2) / 0.0001);
401	    double r = 1.2 * exp(-pow(phase - pos, 2) / (width * 0.1));
402	    double s = -0.2 * exp(-pow(phase - (pos + 0.02), 2) / 0.0002);
403	    return q + r + s;
404	  }
