import 'dart:async';
import 'dart:io';
import 'dart:math';
import 'dart:typed_data';
import 'package:ble_peripheral/ble_peripheral.dart';
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import 'package:permission_handler/permission_handler.dart';

void main() {
  runApp(const EcgTesterApp());
}

class EcgTesterApp extends StatelessWidget {
  const EcgTesterApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'ECG Medical Tester',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        brightness: Brightness.dark,
        primarySwatch: Colors.teal,
        scaffoldBackgroundColor: const Color(0xFF0D1B2A),
        textTheme: GoogleFonts.interTextTheme(ThemeData.dark().textTheme),
      ),
      home: const TesterDashboard(),
    );
  }
}

enum EcgPattern {
  normal,
  mi,
  tachycardia,
  heartFailure,
  conduction,
  noisy,
  leadsOff,
}

class TesterDashboard extends StatefulWidget {
  const TesterDashboard({super.key});

  @override
  State<TesterDashboard> createState() => _TesterDashboardState();
}

class _TesterDashboardState extends State<TesterDashboard> {
  bool _initialized = false;
  bool _advertising = false;
  bool _connected = false;
  bool _bonded = false;
  bool _subscribed = false;

  EcgPattern _currentPattern = EcgPattern.normal;
  final int _sampleRate = 250; // Hz
  double _timerTime = 0.0;
  Timer? _generationTimer;

  static const int _frameHeaderBytes = 1;
  static const int _sampleBytes = 6;
  static const int _defaultPayloadCapBytes = 20;
  static const int _maxPayloadCapBytes = 185;

  int _payloadCapBytes = _defaultPayloadCapBytes;

  // Stats
  int _packetsSent = 0;
  int _sendErrors = 0;
  int _droppedTicks = 0;
  bool _sendInFlight = false;

  final String _deviceName = "ECG Tester";
  static const String _serviceUuid = '0000ec90-0000-1000-8000-00805f9b34fb';
  static const String _charUuid = '0000ec91-0000-1000-8000-00805f9b34fb';

  @override
  void initState() {
    super.initState();
    _initBle();
  }

  Future<void> _initBle() async {
    try {
      await BlePeripheral.initialize();

      BlePeripheral.setAdvertisingStatusUpdateCallback((
        bool advertising,
        String? error,
      ) {
        if (mounted) setState(() => _advertising = advertising);
      });

      BlePeripheral.setConnectionStateChangeCallback((
        String deviceId,
        bool connected,
      ) {
        if (mounted) {
          setState(() {
            _connected = connected;
            if (!connected) {
              _bonded = false;
              _subscribed = false;
            }
          });
        }
        if (!connected) {
          _restartAdvertisingIfNeeded();
        }
      });

      BlePeripheral.setBondStateChangeCallback((
        String deviceId,
        BondState bondState,
      ) {
        if (!mounted) return;
        setState(() {
          _bonded = bondState == BondState.bonded;
        });
      });

      BlePeripheral.setCharacteristicSubscriptionChangeCallback((
        String deviceId,
        String characteristicId,
        bool isSubscribed,
        String? name,
      ) {
        if (!mounted) return;
        if (characteristicId.toLowerCase() == _charUuid.toLowerCase()) {
          setState(() {
            _subscribed = isSubscribed;
          });
        }
      });

      BlePeripheral.setServiceAddedCallback((String serviceId, String? error) {
        debugPrint('Service added: $serviceId error=$error');
      });

      await BlePeripheral.addService(
        BleService(
          uuid: _serviceUuid,
          primary: true,
          characteristics: [
            BleCharacteristic(
              uuid: _charUuid,
              properties: [
                CharacteristicProperties.read.index,
                CharacteristicProperties.notify.index,
              ],
              permissions: [AttributePermissions.readable.index],
            ),
          ],
        ),
      );

      // Allow time for the GATT server to fully register the service
      // before we expose advertising controls.
      await Future.delayed(const Duration(milliseconds: 500));

      if (!mounted) return;
      setState(() => _initialized = true);
    } catch (e) {
      debugPrint('BLE Init failed: $e');
    }
  }

  int _androidSdkInt() {
    final match = RegExp(
      r'SDK\s*(\d+)',
    ).firstMatch(Platform.operatingSystemVersion);
    return int.tryParse(match?.group(1) ?? '') ?? 31;
  }

  Future<bool> _ensureBlePermissions() async {
    if (!Platform.isAndroid) return true;

    final sdkInt = _androidSdkInt();
    if (sdkInt >= 31) {
      final statuses = await [
        Permission.bluetoothAdvertise,
        Permission.bluetoothConnect,
      ].request();
      return (statuses[Permission.bluetoothAdvertise]?.isGranted ?? false) &&
          (statuses[Permission.bluetoothConnect]?.isGranted ?? false);
    }

    final locationStatus = await Permission.locationWhenInUse.request();
    return locationStatus.isGranted;
  }

  @override
  void dispose() {
    _generationTimer?.cancel();
    BlePeripheral.stopAdvertising();
    super.dispose();
  }

  void _toggleAdvertising() async {
    if (_advertising) {
      await BlePeripheral.stopAdvertising();
      _generationTimer?.cancel();
      if (mounted) {
        setState(() {
          _advertising = false;
          _bonded = false;
          _subscribed = false;
        });
      }
      return;
    }

    final hasPermissions = await _ensureBlePermissions();
    if (!hasPermissions) {
      debugPrint('BLE permissions denied, cannot advertise');
      return;
    }

    try {
      await BlePeripheral.startAdvertising(
        services: [_serviceUuid],
        localName: "ECG",
      );
      _startGeneration();
      if (mounted) setState(() => _advertising = true);
    } catch (e) {
      debugPrint('Advertising failed: $e');
      try {
        await BlePeripheral.startAdvertising(services: [], localName: "ECG");
        _startGeneration();
        if (mounted) setState(() => _advertising = true);
      } catch (fallbackError) {
        debugPrint('Advertising fallback failed: $fallbackError');
      }
    }
  }

  int _samplesPerPacket() {
    final available = _payloadCapBytes - _frameHeaderBytes;
    final samples = available ~/ _sampleBytes;
    return samples < 1 ? 1 : samples;
  }

  bool _isSizeError(Object error) {
    final message = error.toString().toLowerCase();
    return message.contains('too large') ||
        message.contains('invalid attribute value length') ||
        message.contains('mtu') ||
        message.contains('133');
  }

  void _applySafePayloadFallback() {
    if (_payloadCapBytes != _defaultPayloadCapBytes) {
      _payloadCapBytes = _defaultPayloadCapBytes;
      _startGeneration();
    }
  }

  Future<void> _restartAdvertisingIfNeeded() async {
    if (_advertising) return;
    try {
      await BlePeripheral.startAdvertising(
        services: [_serviceUuid],
        localName: "ECG",
      );
      if (mounted) setState(() => _advertising = true);
    } catch (e) {
      debugPrint('Re-advertising failed: $e');
    }
  }

  void _startGeneration() {
    _generationTimer?.cancel();
    _packetsSent = 0;
    _sendErrors = 0;
    _droppedTicks = 0;
    _sendInFlight = false;
    _timerTime = 0;

    final samplesPerPacket = _samplesPerPacket();
    final intervalMs = max(1, 1000 * samplesPerPacket ~/ _sampleRate);
    final interval = Duration(milliseconds: intervalMs);

    _generationTimer = Timer.periodic(interval, (timer) {
      if (_sendInFlight) return;
      if (!_advertising && !_connected) return;
      _sendInFlight = true;

      () async {
        try {
          final byteData = ByteData(
            _frameHeaderBytes + samplesPerPacket * _sampleBytes,
          );
          byteData.setUint8(0, 0xEC);

          for (int i = 0; i < samplesPerPacket; i++) {
            final rawLeads = _generateSample();
            final int baseOffset = _frameHeaderBytes + i * _sampleBytes;
            byteData.setInt16(baseOffset, rawLeads[0], Endian.little);
            byteData.setInt16(baseOffset + 2, rawLeads[1], Endian.little);
            byteData.setInt16(baseOffset + 4, rawLeads[2], Endian.little);
            _timerTime += 1.0 / _sampleRate;
          }

          final bytes = byteData.buffer.asUint8List();

          if (bytes.length > _payloadCapBytes ||
              bytes.length > _maxPayloadCapBytes) {
            if (mounted) {
              setState(() {
                _droppedTicks++;
              });
            }
            return;
          }

          await BlePeripheral.updateCharacteristic(
            characteristicId: _charUuid,
            value: bytes,
          );
          if (mounted) {
            setState(() {
              _packetsSent++;
            });
          }
        } catch (e) {
          if (mounted) {
            setState(() {
              _sendErrors++;
              _droppedTicks++;
            });
          }
          debugPrint('Send error: $e');
          if (_isSizeError(e)) {
            _applySafePayloadFallback();
          }
        } finally {
          _sendInFlight = false;
        }
      }();
    });
  }

  List<int> _generateSample() {
    if (_currentPattern == EcgPattern.leadsOff) return [-1, -1, -1];

    double hr = 75;
    if (_currentPattern == EcgPattern.tachycardia) hr = 140;
    if (_currentPattern == EcgPattern.heartFailure) hr = 55;

    final double beatInterval = 60.0 / hr;
    final double phase = (_timerTime % beatInterval) / beatInterval;

    double p = _wave(phase, 0.1, 0.05, 0.02);
    double qrs = _qrs(phase, 0.15, 0.05);
    double t = _wave(phase, 0.35, 0.12, 0.06);

    double leadI = 0.0;
    double leadII = 0.0;
    double leadIII = 0.0;

    switch (_currentPattern) {
      case EcgPattern.mi:
        double stElevation = _wave(phase, 0.22, 0.1, 0.08);
        leadII = p + qrs + t + stElevation;
        leadI = p + (qrs * 0.7) + (t * 0.5);
        break;
      case EcgPattern.heartFailure:
        leadII = (p + qrs + (t * 1.5)) * 0.4;
        leadI = (p + (qrs * 0.6) + t) * 0.3;
        break;
      case EcgPattern.conduction:
        double wideQrs = _qrs(phase, 0.15, 0.12);
        leadII = p + wideQrs + t;
        leadI = p + (wideQrs * 0.8) + (t * 0.6);
        break;
      case EcgPattern.noisy:
        final noise = (Random().nextDouble() - 0.5) * 0.4;
        leadII = p + qrs + t + noise;
        leadI = p + qrs + t + noise;
        break;
      default:
        leadII = p + qrs + t;
        leadI = p + (qrs * 0.8) + (t * 0.7);
    }

    leadIII = leadII - leadI;

    int toAdc(double val) => (2048 + (val * 1000)).clamp(0, 4094).toInt();
    return [toAdc(leadI), toAdc(leadII), toAdc(leadIII)];
  }

  double _wave(double phase, double pos, double width, double amp) {
    return amp * exp(-pow(phase - pos, 2) / (2 * pow(width, 2)));
  }

  double _qrs(double phase, double pos, double width) {
    double q = -0.1 * exp(-pow(phase - (pos - 0.02), 2) / 0.0001);
    double r = 1.2 * exp(-pow(phase - pos, 2) / (width * 0.1));
    double s = -0.2 * exp(-pow(phase - (pos + 0.02), 2) / 0.0002);
    return q + r + s;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: CustomScrollView(
        slivers: [
          _buildAppBar(),
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _buildControlPanel(),
                  const SizedBox(height: 24),
                  const Text(
                    "DIAGNOSTIC TEST PATTERNS",
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.bold,
                      color: Colors.white38,
                      letterSpacing: 1.2,
                    ),
                  ),
                  const SizedBox(height: 12),
                  _buildPatternGrid(),
                  const SizedBox(height: 32),
                  _buildStatusFooter(),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildAppBar() {
    return SliverAppBar(
      expandedHeight: 120,
      pinned: true,
      backgroundColor: const Color(0xFF1A2332),
      flexibleSpace: FlexibleSpaceBar(
        title: Text(
          "ECG Medical Tester",
          style: GoogleFonts.outfit(fontWeight: FontWeight.bold),
        ),
        background: Container(
          decoration: const BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [Color(0xFF1A2332), Color(0xFF0D1B2A)],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildControlPanel() {
    return Container(
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(
        color: const Color(0xFF1A2332),
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: const Color(0xFF263545)),
      ),
      child: Column(
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    _advertising ? "ADVERTISING" : "IDLE",
                    style: TextStyle(
                      color: _advertising ? Colors.tealAccent : Colors.white24,
                      fontSize: 13,
                      fontWeight: FontWeight.w800,
                      letterSpacing: 1,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    _deviceName,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ],
              ),
              Switch.adaptive(
                value: _advertising,
                onChanged: _initialized ? (_) => _toggleAdvertising() : null,
                activeThumbColor: Colors.tealAccent,
              ),
            ],
          ),
          const Divider(height: 40, color: Color(0xFF263545)),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceAround,
            children: [
              _buildMetric("CHANNELS", "3 Lead"),
              _buildMetric("SAMPLE RATE", "${_sampleRate}Hz"),
              _buildMetric("SENT", _packetsSent.toString()),
            ],
          ),
          const SizedBox(height: 10),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceAround,
            children: [
              _buildMetric(
                "PKT SIZE",
                "${_frameHeaderBytes + _samplesPerPacket() * _sampleBytes}B",
              ),
              _buildMetric("SEND ERR", _sendErrors.toString()),
              _buildMetric("DROPPED", _droppedTicks.toString()),
            ],
          ),
          const SizedBox(height: 12),
          Text(
            "Service: $_serviceUuid",
            style: const TextStyle(color: Colors.white12, fontSize: 10),
          ),
          Text(
            "Char: $_charUuid",
            style: const TextStyle(color: Colors.white12, fontSize: 10),
          ),
        ],
      ),
    );
  }

  Widget _buildMetric(String label, String value) {
    return Column(
      children: [
        Text(
          label,
          style: const TextStyle(
            color: Colors.white24,
            fontSize: 10,
            letterSpacing: 0.5,
          ),
        ),
        const SizedBox(height: 6),
        Text(
          value,
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold,
            fontSize: 16,
          ),
        ),
      ],
    );
  }

  Widget _buildPatternGrid() {
    return GridView.count(
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      crossAxisCount: 2,
      mainAxisSpacing: 12,
      crossAxisSpacing: 12,
      childAspectRatio: 2.2,
      children: [
        _buildPatternBtn(
          EcgPattern.normal,
          "Normal Sinus",
          Icons.favorite,
          Colors.tealAccent,
        ),
        _buildPatternBtn(
          EcgPattern.mi,
          "Myocardial Inf.",
          Icons.warning_amber,
          Colors.redAccent,
        ),
        _buildPatternBtn(
          EcgPattern.heartFailure,
          "Heart Failure",
          Icons.heart_broken,
          Colors.orangeAccent,
        ),
        _buildPatternBtn(
          EcgPattern.conduction,
          "Conduction Dist.",
          Icons.electric_bolt,
          Colors.blueAccent,
        ),
        _buildPatternBtn(
          EcgPattern.tachycardia,
          "Tachycardia",
          Icons.speed,
          Colors.yellowAccent,
        ),
        _buildPatternBtn(
          EcgPattern.noisy,
          "Noisy Signal",
          Icons.graphic_eq,
          Colors.purpleAccent,
        ),
      ],
    );
  }

  Widget _buildPatternBtn(
    EcgPattern pattern,
    String label,
    IconData icon,
    Color color,
  ) {
    final bool isSelected = _currentPattern == pattern;
    return GestureDetector(
      onTap: () => setState(() => _currentPattern = pattern),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 200),
        decoration: BoxDecoration(
          color: isSelected
              ? color.withValues(alpha: 0.1)
              : const Color(0xFF1A2332),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: isSelected ? color : const Color(0xFF263545),
            width: 1.5,
          ),
        ),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(icon, color: isSelected ? color : Colors.white24, size: 20),
            const SizedBox(width: 8),
            Text(
              label,
              style: TextStyle(
                color: isSelected ? Colors.white : Colors.white38,
                fontSize: 13,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildStatusFooter() {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.tealAccent.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.tealAccent.withValues(alpha: 0.1)),
      ),
      child: Column(
        children: [
          Row(
            children: [
              Icon(
                Icons.check_circle_outline,
                color: _connected ? Colors.tealAccent : Colors.white24,
                size: 18,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                  _connected
                      ? "Successfully linked with Cardio App."
                      : "GATT Service published. Waiting for connection...",
                  style: TextStyle(
                    color: _connected ? Colors.tealAccent : Colors.white38,
                    fontSize: 12,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              Expanded(
                child: Text(
                  'Bond: ${_bonded ? 'Ready' : 'Pending'}',
                  style: TextStyle(
                    color: _bonded ? Colors.tealAccent : Colors.white38,
                    fontSize: 11,
                  ),
                ),
              ),
              Expanded(
                child: Text(
                  'Subscribe: ${_subscribed ? 'Active' : 'Pending'}',
                  textAlign: TextAlign.right,
                  style: TextStyle(
                    color: _subscribed ? Colors.tealAccent : Colors.white38,
                    fontSize: 11,
                  ),
                ),
              ),
            ],
          ),
          if (!_initialized)
            const Padding(
              padding: EdgeInsets.only(top: 8),
              child: Text(
                "⚠️ Device initializing BLE permissions...",
                style: TextStyle(color: Colors.orangeAccent, fontSize: 11),
              ),
            ),
        ],
      ),
    );
  }
}

