Future<bool> _discoverAndSubscribe(BluetoothDevice device) async {
  BluetoothCharacteristic? ecgChar;
  for (int attempt = 0; attempt < 3 && ecgChar == null; attempt++) {
    if (attempt > 0) {
      await Future.delayed(const Duration(milliseconds: 500));
    }
    List<BluetoothService> services;
    try {
      services = await device.discoverServices();
    } catch (e) {
      debugPrint('BLE service discovery failed (attempt $attempt): $e');
      continue;
    }
    debugPrint(
      'Discovered ${services.length} services: ${services.map((s) => s.uuid).join(', ')}',
    );
    ecgChar = _findExactEcgCharacteristic(services);
  }

  if (ecgChar == null) {
    debugPrint(
      'ECG service/characteristic not found after 3 attempts. Aborting subscribe.',
    );
    return false;
  }

  return _subscribeToCharacteristic(ecgChar);
}

