Future<bool> _subscribeToCharacteristic(
  BluetoothCharacteristic characteristic,
) async {
  _notifyAttemptCount++;
  try {
    final cccdGuid = Guid('00002902-0000-1000-8000-00805f9b34fb');
    final hasCccd = characteristic.descriptors.any(
      (d) => d.uuid == cccdGuid,
    );
    debugPrint(
      'Char ${characteristic.uuid}: descriptors=${characteristic.descriptors.length}, hasCCCD=$hasCccd, props=${characteristic.properties}',
    );

    // Listen BEFORE enabling notify so we don't miss early packets.
    final sub = characteristic.onValueReceived.listen(
      (value) {
        _rawNotificationCount++;
        _rawNotificationBytes += value.length;
        _parseBinaryEcgData(value);
      },
      onError: (e) {
        debugPrint('BLE characteristic stream error: $e');
      },
    );
    _subscriptions.add(sub);

    await characteristic.setNotifyValue(true);

    // Some peripherals (or stale GATT caches) don't expose CCCD via discovery
    // but the descriptor exists server-side. Manually write CCCD as fallback
    // to guarantee the peripheral sees the subscription request.
    if (hasCccd) {
      try {
        final cccd = characteristic.descriptors.firstWhere(
          (d) => d.uuid == cccdGuid,
        );
        await cccd.write([0x01, 0x00]);
        debugPrint('CCCD manually written 0x0100 (notify enable)');
      } catch (e) {
        debugPrint('CCCD manual write failed (non-fatal): $e');
      }
    } else {
      debugPrint(
        'WARNING: no CCCD descriptor visible on ${characteristic.uuid} — peripheral may not register subscription.',
      );
    }

    _notifySuccessCount++;
    _subscribedCharacteristic = characteristic;
    debugPrint(
      'Subscribed to ${characteristic.uuid} from ${characteristic.serviceUuid}, isNotifying=${characteristic.isNotifying}',
    );
    return true;
  } catch (e) {
    debugPrint(
      'BLE notify subscription failed for ${characteristic.uuid}: $e',
    );
    return false;
  }
}

