import 'dart:async';
import 'dart:io';
import 'package:flutter/foundation.dart';
import 'package:flutter_blue_plus/flutter_blue_plus.dart';
import 'package:permission_handler/permission_handler.dart';
import 'ecg_data_model.dart';

class BleService {
  static const String _deviceName = 'ECG';
  static const String _serviceUuid = '0000ec90-0000-1000-8000-00805f9b34fb';
  static const String _charUuid = '0000ec91-0000-1000-8000-00805f9b34fb';

  static const int _binaryHeader = 0xEC;
  static const int _frameHeaderBytes = 1;
  static const int _bytesPerSample = 6;

  int _invalidHeaderCount = 0;
  int _malformedPacketCount = 0;
  int _droppedPacketCount = 0;
  int _notifyAttemptCount = 0;
  int _notifySuccessCount = 0;
  int _rawNotificationCount = 0;
  int _rawNotificationBytes = 0;
  int _parsedBatchCount = 0;
  int _emittedSampleCount = 0;

  BluetoothDevice? _device;
  BluetoothCharacteristic? _subscribedCharacteristic;
  final _ecgController = StreamController<List<EcgSample>>.broadcast();
  final _connectionController = StreamController<bool>.broadcast();
  final _scanController = StreamController<bool>.broadcast();
  final List<StreamSubscription> _subscriptions = [];

  bool _connected = false;
  bool _isScanning = false;

  Stream<List<EcgSample>> get ecgStream => _ecgController.stream;
  Stream<bool> get connectionStream => _connectionController.stream;
  Stream<bool> get scanStream => _scanController.stream;

  bool get isConnected => _connected;
  bool get isScanning => _isScanning;

  int get invalidHeaderCount => _invalidHeaderCount;
  int get malformedPacketCount => _malformedPacketCount;
  int get droppedPacketCount => _droppedPacketCount;
  int get notifyAttemptCount => _notifyAttemptCount;
  int get notifySuccessCount => _notifySuccessCount;
  int get rawNotificationCount => _rawNotificationCount;
  int get rawNotificationBytes => _rawNotificationBytes;
  int get parsedBatchCount => _parsedBatchCount;
  int get emittedSampleCount => _emittedSampleCount;

  int _androidSdkInt() {
    final match = RegExp(
      r'SDK\s*(\d+)',
    ).firstMatch(Platform.operatingSystemVersion);
    return int.tryParse(match?.group(1) ?? '') ?? 31;
  }

  void _resetDiagnostics() {
    _invalidHeaderCount = 0;
    _malformedPacketCount = 0;
    _droppedPacketCount = 0;
    _notifyAttemptCount = 0;
    _notifySuccessCount = 0;
    _rawNotificationCount = 0;
    _rawNotificationBytes = 0;
    _parsedBatchCount = 0;
    _emittedSampleCount = 0;
  }

  Future<bool> _ensureBlePermissions() async {
    if (!Platform.isAndroid) return true;

    final sdkInt = _androidSdkInt();
    if (sdkInt >= 31) {
      final statuses = await [
        Permission.bluetoothScan,
        Permission.bluetoothConnect,
      ].request();
      return (statuses[Permission.bluetoothScan]?.isGranted ?? false) &&
          (statuses[Permission.bluetoothConnect]?.isGranted ?? false);
    }

    return (await Permission.locationWhenInUse.request()).isGranted;
  }

  Future<void> startScanAndConnect() async {
    if (_connected || _isScanning) return;

    _resetDiagnostics();
    _subscribedCharacteristic = null;

    final hasPermissions = await _ensureBlePermissions();
    if (!hasPermissions) {
      _setScanning(false);
      debugPrint('BLE permissions denied, cannot scan/connect');
      return;
    }

    _setScanning(true);

    try {
      final connectedDevices = FlutterBluePlus.connectedDevices;
      for (var d in connectedDevices) {
        if (_isEcgDevice(d)) {
          await _connectAndListen(d);
          _setScanning(false);
          return;
        }
      }

      await FlutterBluePlus.startScan(
        withServices: [Guid(_serviceUuid)],
        withNames: [_deviceName, 'ECG', 'ECG Tester'],
        timeout: const Duration(seconds: 15),
      );

      final subscription = FlutterBluePlus.onScanResults.listen(
        (results) async {
          for (var r in results) {
            if (_isEcgDevice(r.device)) {
              FlutterBluePlus.stopScan();
              await _connectAndListen(r.device);
              return;
            }
          }
        },
        onError: (e) {
          debugPrint('BLE scan results error: $e');
          _setScanning(false);
        },
      );
      _subscriptions.add(subscription);

      final scanStateSub = FlutterBluePlus.isScanning.listen((state) {
        if (!state && _isScanning) _setScanning(false);
      });
      _subscriptions.add(scanStateSub);
    } catch (e) {
      debugPrint('BLE scan/connect failed: $e');
      _setScanning(false);
    }
  }

  bool _isEcgDevice(BluetoothDevice device) {
    final name = (device.advName.isEmpty ? device.platformName : device.advName)
        .toLowerCase();
    return name.contains('ecg');
  }

  void _setScanning(bool val) {
    _isScanning = val;
    _scanController.add(val);
  }

  Future<void> _connectAndListen(BluetoothDevice device) async {
    _device = device;
    _setScanning(false);

    try {
      if (device.isDisconnected) {
        await device.connect(autoConnect: false);
      }
    } catch (e) {
      debugPrint('BLE connect failed: $e');
      _connected = false;
      _connectionController.add(false);
      return;
    }

    if (Platform.isAndroid) {
      try {
        await device.requestMtu(517);
      } catch (e) {
        debugPrint('BLE MTU request failed: $e');
      }
    }

    final connSub = device.connectionState.listen((state) {
      if (state == BluetoothConnectionState.disconnected) {
        _subscribedCharacteristic = null;
        _connected = false;
        _connectionController.add(false);
        Future.delayed(const Duration(seconds: 3), () {
          if (!_connected) startScanAndConnect();
        });
      }
    });
    _subscriptions.add(connSub);

    final subscribed = await _discoverAndSubscribe(device);
    if (!subscribed) {
      _connected = false;
      _connectionController.add(false);
      try {
        await device.disconnect();
      } catch (e) {
        debugPrint('BLE disconnect after subscribe failure: $e');
      }
      return;
    }

    _connected = true;
    _connectionController.add(true);
  }

  Future<bool> _discoverAndSubscribe(BluetoothDevice device) async {
    BluetoothCharacteristic? ecgChar;
    for (int attempt = 0; attempt < 3 && ecgChar == null; attempt++) {
      if (attempt > 0) {
        await Future.delayed(const Duration(milliseconds: 500));
      }
      List<BluetoothService> services;
      try {
        services = await device.discoverServices();
      } catch (e) {
        debugPrint('BLE service discovery failed (attempt $attempt): $e');
        continue;
      }
      debugPrint(
        'Discovered ${services.length} services: ${services.map((s) => s.uuid).join(', ')}',
      );
      ecgChar = _findExactEcgCharacteristic(services);
    }

    if (ecgChar == null) {
      debugPrint(
        'ECG service/characteristic not found after 3 attempts. Aborting subscribe.',
      );
      return false;
    }

    return _subscribeToCharacteristic(ecgChar);
  }

  BluetoothCharacteristic? _findExactEcgCharacteristic(
    List<BluetoothService> services,
  ) {
    final wantService = Guid(_serviceUuid);
    final wantChar = Guid(_charUuid);
    for (final service in services) {
      if (service.uuid != wantService) continue;
      for (final char in service.characteristics) {
        if (char.uuid == wantChar) return char;
      }
    }
    return null;
  }

  Future<bool> _subscribeToCharacteristic(
    BluetoothCharacteristic characteristic,
  ) async {
    _notifyAttemptCount++;
    try {
      // Listen BEFORE enabling notify so we don't miss early packets.
      final sub = characteristic.onValueReceived.listen(
        (value) {
          _rawNotificationCount++;
          _rawNotificationBytes += value.length;
          _parseBinaryEcgData(value);
        },
        onError: (e) {
          debugPrint('BLE characteristic stream error: $e');
        },
      );
      _subscriptions.add(sub);

      await characteristic.setNotifyValue(true);

      _notifySuccessCount++;
      _subscribedCharacteristic = characteristic;
      debugPrint(
        'Subscribed to ${characteristic.uuid} (descriptors=${characteristic.descriptors.length}, props=${characteristic.properties}), isNotifying=${characteristic.isNotifying}',
      );
      return true;
    } catch (e) {
      debugPrint(
        'BLE notify subscription failed for ${characteristic.uuid}: $e',
      );
      return false;
    }
  }

  void _parseBinaryEcgData(List<int> value) {
    if (value.isEmpty) {
      _droppedPacketCount++;
      return;
    }

    try {
      if (value[0] != _binaryHeader) {
        _invalidHeaderCount++;
        _droppedPacketCount++;
        debugPrint(
          'Invalid binary header: ${value[0]} (count=$_invalidHeaderCount)',
        );
        return;
      }

      final payloadBytes = value.length - _frameHeaderBytes;
      if (payloadBytes <= 0 || payloadBytes % _bytesPerSample != 0) {
        _malformedPacketCount++;
        _droppedPacketCount++;
        debugPrint(
          'Malformed packet length: ${value.length} (count=$_malformedPacketCount)',
        );
        return;
      }

      final data = Uint8List.fromList(value);
      final byteData = ByteData.view(data.buffer);

      final sampleCount = payloadBytes ~/ _bytesPerSample;
      if (sampleCount <= 0) {
        _droppedPacketCount++;
        return;
      }

      final samples = <EcgSample>[];
      for (int i = 0; i < sampleCount; i++) {
        final offset = _frameHeaderBytes + i * _bytesPerSample;

        final leadI = byteData.getInt16(offset, Endian.little);
        final leadII = byteData.getInt16(offset + 2, Endian.little);
        final leadIII = byteData.getInt16(offset + 4, Endian.little);

        samples.add(
          EcgSample(
            leadI: leadI,
            leadII: leadII,
            leadIII: leadIII,
            timestamp: DateTime.now(),
          ),
        );
      }

      final validSamples = samples.where((s) => !s.leadsOff).toList();
      if (validSamples.isNotEmpty) {
        _parsedBatchCount++;
        _emittedSampleCount += validSamples.length;
        _ecgController.add(validSamples);
      } else {
        _droppedPacketCount++;
      }
    } catch (e) {
      _droppedPacketCount++;
      debugPrint('Binary parse error: $e');
    }
  }

  Future<void> disconnect() async {
    FlutterBluePlus.stopScan();
    for (final sub in _subscriptions) {
      sub.cancel();
    }
    _subscriptions.clear();

    try {
      await _subscribedCharacteristic?.setNotifyValue(false);
    } catch (_) {}

    _subscribedCharacteristic = null;
    await _device?.disconnect();
    _device = null;
    _connected = false;
    _isScanning = false;
    _resetDiagnostics();
    _connectionController.add(false);
    _scanController.add(false);
  }

  void dispose() {
    disconnect();
    _ecgController.close();
    _connectionController.close();
    _scanController.close();
  }
}

/// Single ECG sample from BLE frame — 3 ADC values (0–4095).
class EcgSample {
  final int leadI;
  final int leadII;
  final int leadIII;
  final DateTime timestamp;

  const EcgSample({
    required this.leadI,
    required this.leadII,
    required this.leadIII,
    required this.timestamp,
  });

  /// Legacy helper for non-BLE JSON fixtures.
  /// Live BLE ingestion uses binary frames parsed in BleService.
  factory EcgSample.fromJson(Map<String, dynamic> json) {
    return EcgSample(
      leadI: (json['I'] as num).toInt(),
      leadII: (json['II'] as num).toInt(),
      leadIII: (json['III'] as num).toInt(),
      timestamp: DateTime.now(),
    );
  }

  /// Check if leads are off (ESP32 sends -1 for disconnected electrodes)
  bool get leadsOff => leadI < 0 || leadII < 0 || leadIII < 0;

  /// Convert ADC values to millivolts (centered around 0)
  List<double> toMillivolts({double vref = 3.3, int adcMax = 4095}) {
    final midpoint = vref / 2.0;
    return [
      ((leadI / adcMax) * vref - midpoint) * 1000.0,
      ((leadII / adcMax) * vref - midpoint) * 1000.0,
      ((leadIII / adcMax) * vref - midpoint) * 1000.0,
    ];
  }
}

/// Legacy parser retained for fixture/offline JSON inputs.
/// Live BLE ingestion uses binary frames parsed in BleService.
List<EcgSample> parseBatchedSamples(Map<String, dynamic> json) {
  if (json.containsKey('samples')) {
    final list = json['samples'] as List<dynamic>;
    return list
        .map((s) => EcgSample.fromJson(s as Map<String, dynamic>))
        .toList();
  }
  // Single sample fallback
  return [EcgSample.fromJson(json)];
}

/// AI prediction result.
class EcgPrediction {
  /// Confidence scores for each class
  final Map<String, double> classConfidences;

  /// Highest-confidence class name
  final String predictedClass;

  /// Confidence of the predicted class (0.0–1.0)
  final double confidence;

  final DateTime timestamp;

  const EcgPrediction({
    required this.classConfidences,
    required this.predictedClass,
    required this.confidence,
    required this.timestamp,
  });

  /// Class names in order
  static const List<String> classNames = ['NORM', 'MI', 'STTC', 'CD', 'HYP'];

  /// Human-readable labels
  static const Map<String, String> classLabels = {
    'NORM': 'Normal',
    'MI': 'Myocardial Infarction',
    'STTC': 'ST/T Change',
    'CD': 'Conduction Disturbance',
    'HYP': 'Hypertrophy',
  };

  /// Color associated with each class (for UI)
  static const Map<String, int> classColors = {
    'NORM': 0xFF4CAF50, // Green
    'MI': 0xFFF44336, // Red
    'STTC': 0xFFFF9800, // Orange
    'CD': 0xFF2196F3, // Blue
    'HYP': 0xFF9C27B0, // Purple
  };

  String get label => classLabels[predictedClass] ?? predictedClass;
  int get colorValue => classColors[predictedClass] ?? 0xFF9E9E9E;
  bool get isNormal => predictedClass == 'NORM';
  bool get isAbnormal => !isNormal && confidence > 0.5;
}

