Widget _buildChart(List<double> data, Color color) {
  final spots = <FlSpot>[];
  for (int i = 0; i < data.length; i++) {
    spots.add(FlSpot(i.toDouble(), data[i]));
  }

  double minY = data.reduce(min);
  double maxY = data.reduce(max);
  double range = maxY - minY;
  if (range < 0.1) range = 1.0;
  minY -= range * 0.1;
  maxY += range * 0.1;

  return LineChart(
    LineChartData(
      minY: minY,
      maxY: maxY,
      clipData: const FlClipData.all(),
      gridData: FlGridData(
        show: true,
        horizontalInterval: range / 4,
        getDrawingHorizontalLine: (value) =>
            FlLine(color: color.withValues(alpha: 0.06), strokeWidth: 0.5),
        drawVerticalLine: true,
        verticalInterval: 62.5,
        getDrawingVerticalLine: (value) =>
            FlLine(color: color.withValues(alpha: 0.04), strokeWidth: 0.5),
      ),
      titlesData: const FlTitlesData(show: false),
      borderData: FlBorderData(show: false),
      lineTouchData: const LineTouchData(enabled: false),
      lineBarsData: [
        LineChartBarData(
          spots: spots,
          isCurved: false,
          color: color,
          barWidth: 1.2,
          dotData: const FlDotData(show: false),
          belowBarData: BarAreaData(
            show: true,
            color: color.withValues(alpha: 0.05),
          ),
        ),
      ],
    ),
  );
}

