int _samplesSinceLastInference = 0;

/// Add incoming ECG samples to the buffer.
void addSamples(List<EcgSample> samples) {
  for (final sample in samples) {
    final mv = sample.toMillivolts(vref: vref, adcMax: adcMax);

    // Shift buffer left, add new sample at end
    for (int ch = 0; ch < numLeads; ch++) {
      _buffer[ch].removeAt(0);
      _buffer[ch].add(mv[ch]);
    }

    _sampleCount++;
    _samplesSinceLastInference++;
  }
}

/// Check if buffer is ready for inference.
bool get isReady =>
    _sampleCount >= windowSize && _samplesSinceLastInference >= strideSize;

/// Get fill percentage (0–100).
double get fillPercentage =>
    min(100.0, (_sampleCount / windowSize) * 100.0);

/// Get the current raw buffer values for visualization (in mV).
/// Returns list of 3 lists, each of length windowSize.
List<List<double>> get rawBuffer =>
    _buffer.map((ch) => List<double>.from(ch)).toList();

