void _onEcgData(List<EcgSample> samples) {
  if (!mounted) return;
  widget.inferenceService.addSamples(samples);

  setState(() {
    for (final sample in samples) {
      final mv = sample.toMillivolts();
      _leadIData.add(mv[0]);
      _leadIIData.add(mv[1]);
      _leadIIIData.add(mv[2]);

      if (_leadIData.length > _visibleSamples) _leadIData.removeAt(0);
      if (_leadIIData.length > _visibleSamples) _leadIIData.removeAt(0);
      if (_leadIIIData.length > _visibleSamples) _leadIIIData.removeAt(0);

      // Simple R-peak detection on Lead II for HR estimation
      _detectRPeak(mv[1]);
    }
  });
}

