import 'dart:async';
import 'package:flutter/foundation.dart';
import 'package:tflite_flutter/tflite_flutter.dart';
import '../../bluetooth/data/ecg_data_model.dart';
import 'ecg_processor.dart';

/// AI Inference Service for real-time ECG classification.
///
/// Loads a TFLite model, processes incoming ECG samples,
/// and emits [EcgPrediction] results with smoothed confidence scores.
class EcgInferenceService {
  static const String _modelPath = 'assets/models/ecg_model.tflite';
  static const double _smoothingAlpha = 0.3;
  static const int _numClasses = 5;

  Interpreter? _interpreter;
  final EcgProcessor _processor = EcgProcessor();
  final _predictionController = StreamController<EcgPrediction>.broadcast();

  // EMA smoothed probabilities
  List<double>? _smoothedProbs;

  bool _modelLoaded = false;

  /// Stream of AI predictions (emits every ~1 second when connected).
  Stream<EcgPrediction> get predictions => _predictionController.stream;

  /// Whether the TFLite model is loaded and ready.
  bool get isModelLoaded => _modelLoaded;

  /// Buffer fill percentage (0–100).
  double get bufferFill => _processor.fillPercentage;

  /// Raw ECG buffer for visualization (3 leads, each 1250 samples in mV).
  List<List<double>> get ecgBuffer => _processor.rawBuffer;

  /// Load the TFLite model from assets.
  Future<void> loadModel() async {
    try {
      _interpreter = await Interpreter.fromAsset(_modelPath);
      _modelLoaded = true;
      debugPrint('ECG TFLite model loaded successfully');
    } catch (e) {
      debugPrint('Failed to load ECG model: $e');
      _modelLoaded = false;
    }
  }

  /// Feed incoming ECG samples from BLE.
  ///
  /// Automatically runs inference when the buffer is ready.
  void addSamples(List<EcgSample> samples) {
    _processor.addSamples(samples);

    if (_processor.isReady && _modelLoaded) {
      _runInference();
    }
  }

  /// Run model inference on the current buffer.
  void _runInference() {
    if (_interpreter == null) return;

    try {
      // Get preprocessed input
      final input = _processor.getProcessedWindow(); // Float32List: 3 × 1250

      // Reshape for model: [1, 3, 1250]
      final inputBuffer = input.buffer.asFloat32List();
      final inputTensor = inputBuffer.reshape([1, 3, EcgProcessor.windowSize]);

      // Output buffer: [1, 5]
      final output = List.generate(
        1,
        (_) => List.filled(_numClasses, 0.0),
      );

      // Run inference
      _interpreter!.run(inputTensor, output);

      // Apply softmax to get probabilities
      final logits = output[0];
      final probs = _softmax(logits);

      // Apply EMA smoothing
      _smoothProbs(probs);

      // Emit prediction
      final bestIdx = _argmax(_smoothedProbs!);
      final prediction = EcgPrediction(
        classConfidences: {
          for (int i = 0; i < _numClasses; i++)
            EcgPrediction.classNames[i]: _smoothedProbs![i],
        },
        predictedClass: EcgPrediction.classNames[bestIdx],
        confidence: _smoothedProbs![bestIdx],
        timestamp: DateTime.now(),
      );

      _predictionController.add(prediction);
    } catch (e) {
      debugPrint('Inference error: $e');
    }
  }

  /// Softmax function.
  List<double> _softmax(List<double> logits) {
    final maxVal = logits.reduce((a, b) => a > b ? a : b);
    final exps = logits.map((v) => _exp(v - maxVal)).toList();
    final sum = exps.fold<double>(0.0, (a, b) => a + b);
    return exps.map((v) => v / sum).toList();
  }

  /// Safe exp to avoid overflow.
  double _exp(double x) {
    if (x > 80) return double.maxFinite;
    if (x < -80) return 0.0;
    return x >= 0
        ? 1.0 + x + x * x / 2 + x * x * x / 6 // Fast approx for small x
        : 1.0 / (1.0 + (-x) + (-x) * (-x) / 2 + (-x) * (-x) * (-x) / 6);
  }

  /// Apply EMA smoothing.
  void _smoothProbs(List<double> probs) {
    if (_smoothedProbs == null) {
      _smoothedProbs = List<double>.from(probs);
    } else {
      for (int i = 0; i < _numClasses; i++) {
        _smoothedProbs![i] =
            _smoothingAlpha * probs[i] + (1 - _smoothingAlpha) * _smoothedProbs![i];
      }
    }

    // Normalize
    final sum = _smoothedProbs!.fold<double>(0.0, (a, b) => a + b);
    if (sum > 0) {
      for (int i = 0; i < _numClasses; i++) {
        _smoothedProbs![i] /= sum;
      }
    }
  }

  int _argmax(List<double> list) {
    int bestIdx = 0;
    for (int i = 1; i < list.length; i++) {
      if (list[i] > list[bestIdx]) bestIdx = i;
    }
    return bestIdx;
  }

  /// Reset processor and smoother.
  void reset() {
    _processor.reset();
    _smoothedProbs = null;
  }

  void dispose() {
    _interpreter?.close();
    _predictionController.close();
  }
}

