import 'dart:math';
import 'dart:typed_data';
import '../../bluetooth/data/ecg_data_model.dart';

/// Real-time ECG preprocessing in Dart.
///
/// Mirrors the Python ECGPreprocessor logic exactly:
///   1. ADC → millivolts conversion
///   2. Ring buffer accumulation
///   3. Simple bandpass approximation (moving average baseline removal)
///   4. Z-score normalization per lead
///
/// Outputs Float32List ready for TFLite inference.
class EcgProcessor {
  /// Target sampling rate (matching ESP32 and model)
  static const int targetFs = 250;

  /// Window duration in seconds
  static const double windowDuration = 5.0;

  /// Samples per window (5 sec × 250 Hz = 1250)
  static const int windowSize = 1250;

  /// Number of leads
  static const int numLeads = 3;

  /// Inference stride in samples (1 sec = 250 samples)
  static const int strideSize = 250;

  /// ESP32 ADC parameters
  static const int adcMax = 4095;
  static const double vref = 3.3;

  // Ring buffer: stores last windowSize samples in millivolts
  final List<List<double>> _buffer = List.generate(
    numLeads,
    (_) => List<double>.filled(windowSize, 0.0, growable: true),
  );
  int _sampleCount = 0;
  int _samplesSinceLastInference = 0;

  /// Add incoming ECG samples to the buffer.
  void addSamples(List<EcgSample> samples) {
    for (final sample in samples) {
      final mv = sample.toMillivolts(vref: vref, adcMax: adcMax);

      // Shift buffer left, add new sample at end
      for (int ch = 0; ch < numLeads; ch++) {
        _buffer[ch].removeAt(0);
        _buffer[ch].add(mv[ch]);
      }

      _sampleCount++;
      _samplesSinceLastInference++;
    }
  }

  /// Check if buffer is ready for inference.
  bool get isReady =>
      _sampleCount >= windowSize && _samplesSinceLastInference >= strideSize;

  /// Get fill percentage (0–100).
  double get fillPercentage =>
      min(100.0, (_sampleCount / windowSize) * 100.0);

  /// Get the current raw buffer values for visualization (in mV).
  /// Returns list of 3 lists, each of length windowSize.
  List<List<double>> get rawBuffer =>
      _buffer.map((ch) => List<double>.from(ch)).toList();

  /// Get preprocessed signal ready for TFLite model.
  ///
  /// Returns Float32List of shape [1, 3, 1250] flattened.
  /// This matches the model input format.
  Float32List getProcessedWindow() {
    _samplesSinceLastInference = 0;

    // Copy buffer data
    final window = List.generate(
      numLeads,
      (ch) => List<double>.from(_buffer[ch]),
    );

    // Step 1: Remove baseline drift (high-pass via moving average subtraction)
    for (int ch = 0; ch < numLeads; ch++) {
      window[ch] = _removeBaseline(window[ch]);
    }

    // Step 2: Z-score normalize each lead
    for (int ch = 0; ch < numLeads; ch++) {
      window[ch] = _normalize(window[ch]);
    }

    // Step 3: Flatten to Float32List [1, 3, 1250]
    final result = Float32List(numLeads * windowSize);
    for (int ch = 0; ch < numLeads; ch++) {
      for (int t = 0; t < windowSize; t++) {
        result[ch * windowSize + t] = window[ch][t];
      }
    }

    return result;
  }

  /// Simple baseline removal: subtract moving average (window = 125 samples = 0.5 sec)
  List<double> _removeBaseline(List<double> signal) {
    const kernelSize = 125; // 0.5 seconds
    final halfKernel = kernelSize ~/ 2;
    final result = List<double>.filled(signal.length, 0.0);

    for (int i = 0; i < signal.length; i++) {
      final start = max(0, i - halfKernel);
      final end = min(signal.length, i + halfKernel + 1);
      double sum = 0;
      for (int j = start; j < end; j++) {
        sum += signal[j];
      }
      final baseline = sum / (end - start);
      result[i] = signal[i] - baseline;
    }

    return result;
  }

  /// Z-score normalization.
  List<double> _normalize(List<double> signal) {
    double mean = 0;
    for (final v in signal) {
      mean += v;
    }
    mean /= signal.length;

    double variance = 0;
    for (final v in signal) {
      variance += (v - mean) * (v - mean);
    }
    final std = sqrt(variance / signal.length);

    if (std < 1e-8) {
      return signal.map((v) => v - mean).toList();
    }

    return signal.map((v) => (v - mean) / std).toList();
  }

  /// Reset the processor.
  void reset() {
    for (int ch = 0; ch < numLeads; ch++) {
      _buffer[ch] = List.filled(windowSize, 0.0);
    }
    _sampleCount = 0;
    _samplesSinceLastInference = 0;
  }
}

