import 'dart:io';
import 'dart:ui';
import 'package:flutter/foundation.dart';
import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import '../../bluetooth/data/ecg_data_model.dart';

/// Notification service for ECG heart alerts.
///
/// Triggers local push notifications when AI detects abnormal patterns.
/// Respects cooldown periods to avoid notification spam.
class NotificationService {
  static final NotificationService _instance = NotificationService._();
  factory NotificationService() => _instance;
  NotificationService._();

  final FlutterLocalNotificationsPlugin _plugin =
      FlutterLocalNotificationsPlugin();

  bool _initialized = false;
  bool _enabled = true;

  /// Cooldown: track last notification time per class
  final Map<String, DateTime> _lastNotified = {};
  static const Duration _cooldown = Duration(seconds: 30);

  /// Confidence threshold to trigger alert
  static const double _alertThreshold = 0.55;

  bool get enabled => _enabled;
  set enabled(bool val) => _enabled = val;

  /// Initialize the notification plugin. Call once at app startup.
  Future<void> init() async {
    if (_initialized) return;

    const androidSettings =
        AndroidInitializationSettings('@mipmap/ic_launcher');
    const initSettings = InitializationSettings(android: androidSettings);

    await _plugin.initialize(
      initSettings,
      onDidReceiveNotificationResponse: _onTap,
    );

    // Request permission on Android 13+
    if (Platform.isAndroid) {
      final android = _plugin.resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin>();
      await android?.requestNotificationsPermission();
    }

    _initialized = true;
    debugPrint('NotificationService initialized');
  }

  void _onTap(NotificationResponse response) {
    // Could navigate to history page in the future
    debugPrint('Notification tapped: ${response.payload}');
  }

  /// Check prediction and fire notification if abnormal.
  void checkAndNotify(EcgPrediction prediction) {
    if (!_enabled || !_initialized) return;
    if (prediction.isNormal) return;
    if (prediction.confidence < _alertThreshold) return;

    final cls = prediction.predictedClass;

    // Cooldown check
    final lastTime = _lastNotified[cls];
    if (lastTime != null &&
        DateTime.now().difference(lastTime) < _cooldown) {
      return;
    }

    _lastNotified[cls] = DateTime.now();
    _fireAlert(prediction);
  }

  Future<void> _fireAlert(EcgPrediction prediction) async {
    final isCritical = prediction.predictedClass == 'MI';
    final channelId = isCritical ? 'ecg_critical' : 'ecg_alert';
    final channelName = isCritical ? 'Critical ECG Alerts' : 'ECG Alerts';
    final importance =
        isCritical ? Importance.max : Importance.high;
    final priority = isCritical ? Priority.max : Priority.high;

    final androidDetails = AndroidNotificationDetails(
      channelId,
      channelName,
      channelDescription: 'Heart rhythm abnormality alerts',
      importance: importance,
      priority: priority,
      enableVibration: true,
      playSound: true,
      icon: '@mipmap/ic_launcher',
      color: const Color(0xFFF44336),
      styleInformation: BigTextStyleInformation(
        _getAlertBody(prediction),
        contentTitle: '⚠️ ${prediction.label} Detected',
      ),
    );

    final details = NotificationDetails(android: androidDetails);
    final confStr = (prediction.confidence * 100).toStringAsFixed(0);

    await _plugin.show(
      prediction.predictedClass.hashCode,
      '⚠️ ${prediction.label} Detected',
      'Confidence: $confStr% — Please consult a cardiologist.',
      details,
      payload: prediction.predictedClass,
    );

    debugPrint(
        'ALERT: ${prediction.label} ($confStr%)');
  }

  String _getAlertBody(EcgPrediction prediction) {
    final confStr = (prediction.confidence * 100).toStringAsFixed(1);
    final descriptions = {
      'MI': 'Possible Myocardial Infarction (heart attack) detected. '
          'Seek immediate medical attention.',
      'STTC': 'ST/T wave changes detected. '
          'This may indicate ischemia or other cardiac conditions.',
      'CD': 'Conduction disturbance detected. '
          'Your heart\'s electrical system may have an irregularity.',
      'HYP': 'Cardiac hypertrophy pattern detected. '
          'This suggests thickened heart muscle.',
    };

    return '${descriptions[prediction.predictedClass] ?? "Abnormal ECG pattern detected."}\n\n'
        'Confidence: $confStr%\n'
        'Time: ${prediction.timestamp.hour.toString().padLeft(2, '0')}:'
        '${prediction.timestamp.minute.toString().padLeft(2, '0')}\n\n'
        '⚕️ This is not a medical diagnosis. Consult a healthcare professional.';
  }
}

