  // Defaults reproduce a healthy sinus beat: P ~0.1, R ~1.4, T ~0.3 mV.
  double pAmp = 0.10, pPos = 0.10, pSig = 0.025;
  double qAmp = -0.08, qPos = 0.18, qSig = 0.010;
  double rAmp = 1.40, rPos = 0.20, rSig = 0.012;
  double sAmp = -0.30, sPos = 0.22, sSig = 0.012;
  double tAmp = 0.30, tPos = 0.40, tSig = 0.060;
  double stPlateau = 0.0; // J-point to T

  double leadIScale = 0.55; // Lead I R amplitude vs Lead II
  double noiseAmp = 0.0;

  switch (_currentPattern) {
    case EcgPattern.mi:
      // Acute MI: ST elevation between J-point and T, T-wave inversion.
      stPlateau = 0.40;
      tAmp = -0.18;
      break;
    case EcgPattern.heartFailure:
      // LVH/strain morphology: tall R, wider QRS, T inversion.
      rAmp = 3.50;
      sSig = 0.024;
      rSig = 0.018;
      tAmp = -0.22;
      break;
    case EcgPattern.conduction:
      // Bundle branch block: wide QRS (~140ms), preserved R height.
      qSig = 0.030;
      rSig = 0.036;
      sSig = 0.036;
      rAmp = 1.55;
      sAmp = -0.45;
      break;
    case EcgPattern.noisy:
      noiseAmp = 0.40;
      break;
    case EcgPattern.tachycardia:
    case EcgPattern.normal:
    case EcgPattern.leadsOff:
      break;
  }

  final double leadII =
      _gauss(phase, pPos, pSig, pAmp) +
          _gauss(phase, qPos, qSig, qAmp) +
          _gauss(phase, rPos, rSig, rAmp) +
          _gauss(phase, sPos, sSig, sAmp) +
          _gauss(phase, tPos, tSig, tAmp) +
          _stPlateau(phase, stPlateau);

  final double leadI =
      _gauss(phase, pPos, pSig, pAmp * 0.6) +
          _gauss(phase, qPos, qSig, qAmp * 0.6) +
          _gauss(phase, rPos, rSig, rAmp * leadIScale) +
          _gauss(phase, sPos, sSig, sAmp * 0.5) +
          _gauss(phase, tPos, tSig, tAmp * 0.7) +
          _stPlateau(phase, stPlateau * 0.5);

  final double leadIII = leadII - leadI;

  final double n1 = noiseAmp == 0 ? 0 : (_rng.nextDouble() - 0.5) * noiseAmp;
  final double n2 = noiseAmp == 0 ? 0 : (_rng.nextDouble() - 0.5) * noiseAmp;
  final double n3 = noiseAmp == 0 ? 0 : (_rng.nextDouble() - 0.5) * noiseAmp;

  // Real ECG full-scale: ±1650 mV across 12-bit ADC at vref=3.3V.
  // R-wave at 1.4 mV → ADC ≈ 3787, comfortably in range.
  int toAdc(double mV) =>
      (2048 + mV * (4095.0 / 3300.0)).clamp(0, 4094).toInt();

  return [toAdc(leadI + n1), toAdc(leadII + n2), toAdc(leadIII + n3)];
