double _gauss(double phase, double pos, double width, double amp) {
  final d = phase - pos;
  return amp * exp(-(d * d) / (2 * width * width));
}

// Flat ST elevation/depression plateau between J-point (~0.24) and T-onset (~0.34).
double _stPlateau(double phase, double amp) {
  if (amp == 0) return 0.0;
  if (phase < 0.24 || phase > 0.34) return 0.0;
