/// Softmax over logits (numerically stable).
List<double> _softmax(List<double> logits) {
  final maxVal = logits.reduce((a, b) => a > b ? a : b);
  final exps = logits.map((v) => math.exp(v - maxVal)).toList();
  final sum = exps.fold<double>(0.0, (a, b) => a + b);
  if (sum <= 0 || sum.isNaN || sum.isInfinite) {
    return List.filled(logits.length, 1.0 / logits.length);
  }
  return exps.map((v) => v / sum).toList();
}

