/// Re-pack leads-first buffer [ch0..,ch1..,ch2..] as time-first [t0_ch0,t0_ch1,t0_ch2, t1_..].
Float32List _toTimeFirst(Float32List leadsFirst, int leads, int time) {
  final out = Float32List(leads * time);
  for (int t = 0; t < time; t++) {
    for (int c = 0; c < leads; c++) {
      out[t * leads + c] = leadsFirst[c * time + t];
    }
  }
  return out;
}

